{
  "data": null
}
"""));
        var httpClient = new HttpClient(handler);
        var client = new GraphQLClient(httpClient, new Uri("https://example.com/graphql"));
        var operation = Substitute.For<global::GraphQL.Sharp.Generated.IGraphQLOperation<DummyResponse, DummyVariables>>();
        operation.OperationName.Returns("TestOp");
        operation.Query.Returns("mutation TestOp { __typename }");
        operation.Variables.Returns(new DummyVariables("value"));
        await client.ExecuteAsync(operation, TestContext.Current.CancellationToken);
        var payload = handler.ContentText.ShouldNotBeNull();
        using var document = JsonDocument.Parse(payload);
        document.RootElement.GetProperty("operationName").GetString()!.ShouldBe("TestOp");
        document.RootElement.GetProperty("query").GetString()!.ShouldContain("TestOp");
        document.RootElement.GetProperty("variables").GetProperty("value").GetString()!.ShouldBe("value");
    }

