    [Fact]
    public async Task ExecuteIncrementalAsync_Parses_Multipart_Response()
    {
        var boundary = "boundary123";
        var body = string.Join("\r\n", new[] { "--" + boundary, "Content-Type: application/json", string.Empty, "{\"data\":null}", "--" + boundary, "Content-Type: application/json", string.Empty, "{\"data\":null}", "--" + boundary + "--" });
        var response = new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent(body, Encoding.UTF8)
        };
        response.Content.Headers.ContentType = new MediaTypeHeaderValue("multipart/mixed");
        response.Content.Headers.ContentType.Parameters.Add(new NameValueHeaderValue("boundary", boundary));
        var handler = new TestHttpMessageHandler(_ => response);
        var httpClient = new HttpClient(handler);
        var client = new GraphQLClient(httpClient, new Uri("https://example.com/graphql"));
        var operation = Substitute.For<global::GraphQL.Sharp.Generated.IGraphQLOperation<DummyResponse, DummyVariables>>();
        operation.OperationName.Returns("TestOp");
        operation.Query.Returns("query TestOp { __typename }");
        operation.Variables.Returns((DummyVariables? )null);
        var results = new List<GraphQLResponse<DummyResponse>>();
        await foreach (var item in client.ExecuteIncrementalAsync(operation, TestContext.Current.CancellationToken))
        {
            results.Add(item);
        }

        results.Count.ShouldBe(2);
    }

