    [Fact]
    public void GraphQLError_Deserializes_Details()
    {
        var json = """
{
  "errors": [
    {
      "message": "bad",
      "locations": [
        {
          "line": 2,
          "column": 4
        }
      ],
      "path": [
        "users",
        0,
        "name"
      ],
      "extensions": {
        "code": "BAD"
      }
    }
  ]
}
""";
        var options = new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true
        };
        var response = JsonSerializer.Deserialize<GraphQLResponse<DummyResponse>>(json, options);
        response.ShouldNotBeNull();
        response.Errors.ShouldNotBeNull();
        response.Errors!.Length.ShouldBe(1);
        var error = response.Errors[0];
        error.Message.ShouldBe("bad");
        error.Locations.ShouldNotBeNull();
        error.Locations![0].Line.ShouldBe(2);
        error.Locations[0].Column.ShouldBe(4);
        error.Path.ShouldNotBeNull();
        error.Path!.Length.ShouldBe(3);
        error.Path[0].GetString().ShouldBe("users");
        error.Path[1].GetInt32().ShouldBe(0);
        error.Path[2].GetString().ShouldBe("name");
        error.Extensions.ShouldNotBeNull();
        error.Extensions!.Value.GetProperty("code").GetString().ShouldBe("BAD");
    }

